a<-commandArgs(TRUE);if(length(a)<3)stop("Usage: time_roc.R <pred.csv> <out> <times>");if(!requireNamespace("timeROC",quietly=TRUE)||!requireNamespace("ggplot2",quietly=TRUE))stop("Install timeROC and ggplot2");d<-read.csv(a[1],check.names=FALSE);out<-a[2];tt<-as.numeric(strsplit(a[3],",",TRUE)[[1]]);mods<-setdiff(names(d),c("ID","Time","Event"));dir.create(out,recursive=TRUE,showWarnings=FALSE);for(t in tt){cur<-list();auc<-data.frame();for(m in mods){o<-timeROC::timeROC(T=d$Time,delta=d$Event,marker=d[[m]],cause=1,weighting="marginal",times=t,iid=TRUE);cur[[m]]<-data.frame(FPR=o$FP[,1],TPR=o$TP[,1],model=m);auc<-rbind(auc,data.frame(time=t,model=m,AUC=o$AUC[1]))};z<-do.call(rbind,cur);write.csv(z,file.path(out,paste0("roc_",t,".csv")),row.names=FALSE);write.csv(auc,file.path(out,paste0("auc_",t,".csv")),row.names=FALSE);p<-ggplot2::ggplot(z,ggplot2::aes(FPR,TPR,color=model))+ggplot2::geom_line(linewidth=.8)+ggplot2::geom_abline(linetype=2,color="grey60")+ggplot2::coord_equal()+ggplot2::theme_classic()+ggplot2::labs(title=paste0(t,"-unit ROC"),x="1 - Specificity",y="Sensitivity",color=NULL);ggplot2::ggsave(file.path(out,paste0("roc_",t,".pdf")),p,width=5,height=5)}
